<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); try { $u = App\Models\User::first(); auth()->login($u); $v = view("layouts.app"); echo substr($v->render(), 0, 50); echo "\nSUCCESS\n"; } catch (\Throwable $e) { echo get_class($e) . "\n" . $e->getMessage() . "\n" . $e->getFile() . ":" . $e->getLine(); }
